=head2 Google::Cloud::Memorystore::V1beta::Memorystore::PscAutoConnection

Details of consumer resources in a PSC connection.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->port() >> / C<< $msg->port($value) >>

Type: C<Int32>

Optional. port will only be set for Primary/Reader or Discovery endpoint.

=item * C<< $msg->psc_connection_id() >> / C<< $msg->psc_connection_id($value) >>

Type: C<String>

Output only. The PSC connection id of the forwarding rule connected to the
service attachment.

=item * C<< $msg->ip_address() >> / C<< $msg->ip_address($value) >>

Type: C<String>

Output only. The IP allocated on the consumer network for the PSC
forwarding rule.

=item * C<< $msg->forwarding_rule() >> / C<< $msg->forwarding_rule($value) >>

Type: C<String>

Output only. The URI of the consumer side forwarding rule.
Format:
projects/{project}/regions/{region}/forwardingRules/{forwarding_rule}

=item * C<< $msg->project_id() >> / C<< $msg->project_id($value) >>

Type: C<String>

Required. The consumer project_id where PSC connections are established.
This should be the same project_id that the instance is being created in.

=item * C<< $msg->network() >> / C<< $msg->network($value) >>

Type: C<String>

Required. The network where the PSC endpoints are created, in the form of
projects/{project_id}/global/networks/{network_name}.

=item * C<< $msg->service_attachment() >> / C<< $msg->service_attachment($value) >>

Type: C<String>

Output only. The service attachment which is the target of the PSC
connection, in the form of
projects/{project-id}/regions/{region}/serviceAttachments/{service-attachment-id}.

=item * C<< $msg->psc_connection_status() >> / C<< $msg->psc_connection_status($value) >>

Type: C<Enum> (L<Google::Cloud::Memorystore::V1beta::PscConnectionStatus>)

Output only. The status of the PSC connection: whether a connection exists
and ACTIVE or it no longer exists. Please note that this value is updated
periodically. Please use Private Service Connect APIs for the latest
status.

=item * C<< $msg->connection_type() >> / C<< $msg->connection_type($value) >>

Type: C<Enum> (L<Google::Cloud::Memorystore::V1beta::ConnectionType>)

Output only. Type of the PSC connection.

=item * C<< $msg->ip_version() >> / C<< $msg->ip_version($value) >>

Type: C<Enum> (L<Google::Cloud::Memorystore::V1beta::IpVersion>)

Optional. Immutable. The IP version used for the PSC auto-created
endpoint. If not specified, defaults to IPV4.

=back

