=head2 Google::Cloud::Memorystore::V1beta::Memorystore::ListAclPoliciesRequest

Request for `ListAclPolicies`.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The resource name of the ACL policy location using the form:
    `projects/{project}/locations/{location}`
where `location` refers to a Google Cloud region.

=item * C<< $msg->page_size() >> / C<< $msg->page_size($value) >>

Type: C<Int32>

Optional. The maximum number of items to return.

If not specified, a default value of 1000 will be used by the service.
Regardless of the page_size value, the response may include a partial list
and a caller should only rely on response's
`next_page_token`
to determine if there are more ACL policies left to be queried.

The maximum value is 1000; values above 1000 will be coerced to 1000.

=item * C<< $msg->page_token() >> / C<< $msg->page_token($value) >>

Type: C<String>

Optional. The `next_page_token` value returned from a previous
`ListAclPolicies` request, if any.

=back

=head2 Google::Cloud::Memorystore::V1beta::Memorystore::ListAclPoliciesResponse

Response for `ListAclPolicies`.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->acl_policies() >> / C<< $msg->acl_policies($value) >>

Type: C<Message> (L<Google::Cloud::Memorystore::V1beta::Memorystore::AclPolicy>)

A list of ACL policies in the project in the specified location,
or across all locations.

If the `location` in the parent field of the request is "-", all regions
available to the project are queried, and the results aggregated.

=item * C<< $msg->next_page_token() >> / C<< $msg->next_page_token($value) >>

Type: C<String>

Token to retrieve the next page of results, or empty if there are no more
results in the list.

=item * C<< $msg->unreachable() >> / C<< $msg->unreachable($value) >>

Type: C<String>

Unordered list. Locations that could not be reached.

=back

