=head2 Google::Cloud::Memorystore::V1beta::Memorystore::CreateAclPolicyRequest

Request for `CreateAclPolicy`.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The resource name of the ACL policy location using the form:
    `projects/{project}/locations/{location}`
where `location` refers to a Google Cloud region.

=item * C<< $msg->acl_policy_id() >> / C<< $msg->acl_policy_id($value) >>

Type: C<String>

Required. The logical name of the ACL policy in the customer project
with the following restrictions:

* Must contain only lowercase letters, numbers, and hyphens.
* Must start with a letter.
* Must be between 1-63 characters.
* Must end with a number or a letter.
* Must be unique within the customer project / location

=item * C<< $msg->acl_policy() >> / C<< $msg->acl_policy($value) >>

Type: C<Message> (L<Google::Cloud::Memorystore::V1beta::Memorystore::AclPolicy>)

Required. The ACL policy that is to be created.

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

Optional. Idempotent request UUID.
.

=back

=head2 Google::Cloud::Memorystore::V1beta::Memorystore::CreateInstanceRequest

Request message for [CreateInstance][].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The parent resource where this instance will be created.
Format: projects/{project}/locations/{location}

=item * C<< $msg->instance_id() >> / C<< $msg->instance_id($value) >>

Type: C<String>

Required. The ID to use for the instance, which will become the final
component of the instance's resource name.

This value is subject to the following restrictions:

* Must be 4-63 characters in length
* Must begin with a letter or digit
* Must contain only lowercase letters, digits, and hyphens
* Must not end with a hyphen
* Must be unique within a location

=item * C<< $msg->instance() >> / C<< $msg->instance($value) >>

Type: C<Message> (L<Google::Cloud::Memorystore::V1beta::Memorystore::Instance>)

Required. The instance to create.

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

Optional. An optional request ID to identify requests. Specify a unique
request ID so that if you must retry your request, the server will know to
ignore the request if it has already been completed. The server will
guarantee that for at least 60 minutes since the first request.

For example, consider a situation where you make an initial request and the
request times out. If you make the request again with the same request
ID, the server can check if original operation with the same request ID
was received, and if so, will ignore the second request. This prevents
clients from accidentally creating duplicate commitments.

The request ID must be a valid UUID with the exception that zero UUID is
not supported (00000000-0000-0000-0000-000000000000).

=back

=head2 Google::Cloud::Memorystore::V1beta::Memorystore::UpdateAclPolicyRequest

